    [22589]={name="Atiesh, Greatstaff of the Guardian",quality=5,ilvl=90,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Atiesh, Greatstaff of the Guardian'.",questName="Atiesh, Greatstaff of the Guardian",lore="The Guardian's staff, broken and scattered. Rebuilding it means gathering forty splinters from Naxxramas, the base from Kel'Thuzad, and carrying it to the ruin of Karazhan where Medivh once held it.",proc="Use: Creates a portal, teleporting group members that use it to Karazhan. (1 Min Cooldown)"},
    [22657]={name="Amulet of the Dawn",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Epic Armaments of Battle - Friend of the Dawn'. Pick it over the other reward choices.",zone="Eastern Plaguelands",questName="Epic Armaments of Battle - Friend of the Dawn",lore="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?"},
