    [23001]={name="Eye of Diminution",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Thaddius.",zone="Naxxramas",npc="Thaddius",lore="Two abominations sewn into one and animated with stolen lightning -- one of Kel'Thuzad's more ambitious experiments in the Construct Quarter.",proc="Use: Reduces the threat you generate by [35 - max(0, Level - 60)]% for 20 sec. (2 Min Cooldown)"},
    [23025]={name="Seal of the Damned",quality=4,ilvl=85,reqLevel=60,sourceType="object_drop",instructions="Found in Bottle of Disease.",npc="Bottle of Disease"},
